    /// <summary>Нормализация перед сравнением: без \r и обрамляющих пробелов.</summary>
    private static string Normalize(string? prompt) => (prompt ?? "").Replace("\r", "").Trim();

    /// <summary>
    /// Старые значения промпта по умолчанию (заглушки ранних версий и прежние базовые промпты без правок)
    /// — при загрузке настроек заменяются на актуальный базовый.
    /// </summary>
    public static bool IsLegacyStub(string? prompt)
    {
        if (string.IsNullOrWhiteSpace(prompt) ||
            prompt.Trim() is "Ты — мастер игры." or "Ты — полезный ассистент." or "Ты — мастер игры")
        {
            return true;
        }

        var hash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Normalize(prompt))));
        return PreviousDefaults.Contains(hash);
    }

    /// <summary>Текст совпадает с текущим базовым промптом из кода.</summary>
    public static bool IsCurrentDefault(string? prompt) =>
        string.Equals(Normalize(prompt), Normalize(Default), StringComparison.Ordinal);

    /// <summary>
    /// Сохранённый промпт можно считать базовым (а не правкой игрока): он пуст, это заглушка ранней
    /// версии, прежний базовый промпт или текущий базовый. Только такой текст обновляем автоматически.
    /// </summary>
    public static bool IsUnmodifiedDefault(string? prompt) =>
        IsLegacyStub(prompt) || IsCurrentDefault(prompt);
